-- RB Badge tables (waitlist-db, binding DB). Safe to run any number of times: every statement is
-- CREATE ... IF NOT EXISTS or INSERT OR IGNORE, so it never overwrites what the owner has edited.
-- artist-router runs this on first use (rb-site-updates/patch_badge.py) and RB Command runs it when a
-- Badges table is missing (rb-command-updates/patch_badges_admin.py). Statements end with ";" + newline.
CREATE TABLE IF NOT EXISTS badge_config (key TEXT PRIMARY KEY, value TEXT, label TEXT, help TEXT, sort_order INTEGER NOT NULL DEFAULT 0, updated_at TEXT);
CREATE TABLE IF NOT EXISTS badge_members (id TEXT PRIMARY KEY, clerk_user_id TEXT NOT NULL UNIQUE, email_norm TEXT, email_at TEXT, display_name TEXT, pass_code TEXT NOT NULL UNIQUE, pass_secret TEXT NOT NULL, created_at TEXT NOT NULL, daily_at TEXT);
CREATE INDEX IF NOT EXISTS badge_members_email ON badge_members (email_norm);
CREATE TABLE IF NOT EXISTS badge_points (id TEXT PRIMARY KEY, member_id TEXT NOT NULL, source TEXT NOT NULL, source_ref TEXT NOT NULL UNIQUE, points INTEGER NOT NULL, note TEXT, actor TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS badge_points_member ON badge_points (member_id, source);
CREATE TABLE IF NOT EXISTS badge_levels (id INTEGER PRIMARY KEY AUTOINCREMENT, level_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, min_points INTEGER NOT NULL DEFAULT 0, perks TEXT, status TEXT NOT NULL DEFAULT 'draft', sort_order INTEGER NOT NULL DEFAULT 0, updated_at TEXT);
CREATE TABLE IF NOT EXISTS badge_rewards (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, cost INTEGER NOT NULL DEFAULT 0, quantity INTEGER NOT NULL DEFAULT 0, remaining INTEGER NOT NULL DEFAULT 0, min_level TEXT, status TEXT NOT NULL DEFAULT 'draft', sort_order INTEGER NOT NULL DEFAULT 0, image_url TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS badge_redemptions (id TEXT PRIMARY KEY, member_id TEXT NOT NULL, reward_id INTEGER NOT NULL, reward_name TEXT, cost INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'requested', email TEXT, notes TEXT, handled_by TEXT, created_at TEXT NOT NULL, updated_at TEXT);
CREATE INDEX IF NOT EXISTS badge_redemptions_status ON badge_redemptions (status, created_at);
CREATE TABLE IF NOT EXISTS badge_achievements (key TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, rule TEXT NOT NULL, threshold INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'live', sort_order INTEGER NOT NULL DEFAULT 0, updated_at TEXT);
CREATE TABLE IF NOT EXISTS badge_grants (member_id TEXT NOT NULL, achievement_key TEXT NOT NULL, granted_by TEXT, created_at TEXT NOT NULL, PRIMARY KEY (member_id, achievement_key));
CREATE TABLE IF NOT EXISTS badge_game_rounds (id TEXT PRIMARY KEY, member_id TEXT NOT NULL, seed INTEGER NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, score INTEGER, points INTEGER);
CREATE INDEX IF NOT EXISTS badge_game_rounds_member ON badge_game_rounds (member_id, started_at);
CREATE TABLE IF NOT EXISTS world_players (id TEXT PRIMARY KEY, name TEXT NOT NULL, clerk_user_id TEXT, net_worth INTEGER NOT NULL DEFAULT 0, tokens INTEGER NOT NULL DEFAULT 0, kills INTEGER NOT NULL DEFAULT 0, deaths INTEGER NOT NULL DEFAULT 0, health INTEGER NOT NULL DEFAULT 100, lng REAL, lat REAL, seen_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS world_players_seen ON world_players (seen_at);
CREATE TABLE IF NOT EXISTS world_chat (n INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT NOT NULL, name TEXT NOT NULL, text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS world_play (member_id TEXT NOT NULL, day TEXT NOT NULL, seconds INTEGER NOT NULL DEFAULT 0, last_beat TEXT, awarded INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (member_id, day));
CREATE TABLE IF NOT EXISTS world_rate (k TEXT NOT NULL, minute TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (k, minute));
CREATE TABLE IF NOT EXISTS world_lots (lot INTEGER PRIMARY KEY, owner_id TEXT, owner_name TEXT, business TEXT, level INTEGER NOT NULL DEFAULT 0, title TEXT, rent_pending INTEGER NOT NULL DEFAULT 0, bought_at TEXT, updated_at TEXT);
CREATE INDEX IF NOT EXISTS world_lots_owner ON world_lots (owner_id);
CREATE TABLE IF NOT EXISTS world_cars (id TEXT PRIMARY KEY, x REAL, z REAL, h REAL, s REAL, level INTEGER NOT NULL DEFAULT 1, color TEXT, at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS world_races (id TEXT PRIMARY KEY, track TEXT NOT NULL, host_id TEXT NOT NULL, host_name TEXT, solo INTEGER NOT NULL DEFAULT 0, start_at INTEGER NOT NULL, ends_at INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS world_races_ends ON world_races (ends_at);
CREATE TABLE IF NOT EXISTS world_race_entries (race_id TEXT NOT NULL, player_id TEXT NOT NULL, name TEXT NOT NULL, slot INTEGER NOT NULL DEFAULT 0, cp INTEGER NOT NULL DEFAULT 0, cp_at INTEGER, finish_ms INTEGER, place INTEGER, x REAL, z REAL, h REAL, s REAL, at INTEGER, PRIMARY KEY (race_id, player_id));
CREATE INDEX IF NOT EXISTS world_race_entries_player ON world_race_entries (player_id);
CREATE TABLE IF NOT EXISTS world_race_best (k TEXT PRIMARY KEY, track TEXT NOT NULL, player_id TEXT NOT NULL, name TEXT NOT NULL, ms INTEGER NOT NULL, race_id TEXT, at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS world_race_best_ms ON world_race_best (track, ms);
CREATE TABLE IF NOT EXISTS badge_rate (member_id TEXT NOT NULL, minute TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (member_id, minute));
INSERT OR IGNORE INTO badge_levels (level_key, name, min_points, perks, status, sort_order) VALUES ('bronze', 'Bronze', 0, 'DRAFT: the owner writes what Bronze members get before this goes live.', 'draft', 1), ('silver', 'Silver', 500, 'DRAFT: the owner writes what Silver members get (for example early ticket access) before this goes live.', 'draft', 2), ('gold', 'Gold', 1500, 'DRAFT: the owner writes what Gold members get (for example guest list at RB shows) before this goes live.', 'draft', 3), ('black', 'Black', 5000, 'DRAFT: the owner writes what Black members get (for example VIP at RB events) before this goes live.', 'draft', 4);
INSERT OR IGNORE INTO badge_achievements (key, name, description, rule, threshold, status, sort_order) VALUES ('first_night', 'First night out', 'Checked in at an RB show or event.', 'checkins', 1, 'live', 1), ('regular', 'Regular', 'Checked in at 5 RB shows or events.', 'checkins', 5, 'live', 2), ('fixture', 'Front row fixture', 'Checked in at 20 RB shows or events.', 'checkins', 20, 'live', 3), ('on_the_list', 'On the list', 'Joined the RB list.', 'signup', 1, 'live', 4), ('supporter', 'Supporter', 'Made a paid order in the RB store.', 'orders', 1, 'live', 5), ('backer', 'Backer', 'Gave to RB at /fund.', 'contributions', 1, 'live', 6), ('member', 'Member', 'Had an active RB Studio membership.', 'member', 1, 'live', 7), ('released', 'Released', 'Had a song approved through RB Release.', 'release', 1, 'live', 8), ('promoter', 'Promoter', 'Had an event listed on RB Events.', 'event_listed', 1, 'live', 9), ('collector', 'Collector', 'Had an RB Collect prize claim approved.', 'collect', 1, 'live', 10), ('club_1k', '1K club', 'Earned 1,000 points in all.', 'lifetime', 1000, 'live', 11), ('club_10k', '10K club', 'Earned 10,000 points in all.', 'lifetime', 10000, 'live', 12), ('founding', 'Founding member', 'Given by the RB team.', 'manual', 1, 'draft', 13);
INSERT OR IGNORE INTO badge_config (key, value, label, help, sort_order) VALUES ('enabled', 'off', 'RB Badge switched on', 'on or off. While off, /badge says RB Badge is coming soon, nobody earns or spends points and the door desk can''t check anyone in. The terms at /badge/terms are always visible so they can be reviewed.', 1), ('eligibility', 'Open to anyone with an RB account and a verified email address.', 'Who can join', 'Shown in the terms. Have this reviewed before switching RB Badge on.', 2), ('redeem_how', 'Pick a reward on your badge and press Redeem. The points are held while RB reviews it, and RB contacts you at the verified email on your account to arrange it. If RB can''t give it, the points go back to you.', 'How rewards are given', 'Shown on the badge and in the terms.', 3), ('points_welcome', '50', 'Welcome points', 'One time, on a member''s first visit to their badge while RB Badge is on.', 10), ('points_daily', '5', 'Points for opening your badge each day', 'Once a day (midnight Pacific) for signed-in members who open their badge.', 11), ('points_signup', '25', 'Points for joining the RB list', 'One time, when the member''s verified email is on the RB list.', 12), ('points_membership_request', '50', 'Points per membership request', 'One time per membership tier, when the member''s verified email joined a waitlist or applied at /memberships.', 13), ('points_per_dollar_spent', '10', 'Points per $1 spent in the store', 'For each whole dollar of a paid store order (read from the store''s order records).', 14), ('order_cap', '5000', 'Most points per store order', 'Upper limit of points from one store order.', 15), ('points_per_dollar_given', '10', 'Points per $1 given at /fund', 'For each whole dollar of a paid contribution.', 16), ('contribution_cap', '5000', 'Most points per contribution', 'Upper limit of points from one contribution.', 17), ('points_member_month', '100', 'Points per month of an active RB Studio membership', 'Once a calendar month (Pacific) while the member''s RB Studio membership is active.', 18), ('points_release', '100', 'Points per song approved on RB Release', 'One time per song submitted with the member''s verified email that RB approves.', 19), ('points_event_listed', '50', 'Points per event listed on RB Events', 'One time per event the member submitted that RB publishes.', 20), ('points_collect', '50', 'Points per approved RB Collect claim', 'One time per RB Collect prize claim that RB approves or delivers.', 21), ('checkin_points', '100', 'Points for a door check-in', 'What the door desk gives by default when staff scan a member''s badge at an RB show or event (once per member per event). Staff can change it per scan up to the most below.', 30), ('checkin_max', '1000', 'Most points for one check-in', 'Upper limit staff can give for one check-in.', 31), ('adjust_max', '10000', 'Most points for one hand adjustment', 'Upper limit for one add or remove by the team in the badge desk.', 32);
INSERT OR IGNORE INTO badge_config (key, value, label, help, sort_order) VALUES ('game_points_round', '20', 'Most points from one round of RB Gold Rush', 'The game in the RB app (relentlessbillionaire.com/app). A round lasts 45 seconds; its points are the score divided by the number below, up to this.', 40), ('game_score_per_point', '10', 'Gold Rush score for 1 point', 'For example 10 means a score of 150 gives 15 points.', 41), ('game_points_daily', '60', 'Most points from Gold Rush a day', 'Upper limit of game points one member can earn each day (midnight Pacific). 0 turns game points off; the game can still be played.', 42), ('game_rounds_daily', '25', 'Most Gold Rush rounds a day', 'How many rounds a member can start each day.', 43);
INSERT OR IGNORE INTO badge_config (key, value, label, help, sort_order) VALUES ('world_points_block', '5', 'RB World: points per stretch of play', 'RB World is the 3D city game at relentlessbillionaire.com/app/world. Members signed in earn this many points for every stretch of play below. 0 turns it off.', 50), ('world_block_minutes', '10', 'RB World: minutes in a stretch of play', 'RB counts the play time itself from the game''s check-ins every few seconds.', 51), ('world_points_daily', '30', 'RB World: most points a day', 'Upper limit of RB World points one member can earn each day (midnight Pacific).', 52);
INSERT OR IGNORE INTO badge_config (key, value, label, help, sort_order) VALUES ('world_open', 'on', 'RB World open', 'on or off. RB World (the 3D city game at relentlessbillionaire.com/game, now at /app/world) is open to everyone while on, whether or not RB Badge is switched on; its play-time points only count once RB Badge is on.', 49);
INSERT OR IGNORE INTO badge_config (key, value, label, help, sort_order) VALUES ('world_radio', 'on', 'RB World car radio', 'on or off. While on, the car radio in RB World plays RB Radio live (the same song as everyone, and live shows when RB goes on air). Players turn it on themselves.', 50);
INSERT OR IGNORE INTO badge_config (key, value, label, help, sort_order) VALUES ('world_combat', 'on', 'RB World combat (18+)', 'on or off. While on, players who confirm they are 18 or older can turn on weapons, combat missions and fights with other players who turned it on too. Off: nobody can.', 52);
INSERT OR IGNORE INTO badge_config (key, value, label, help, sort_order) VALUES ('world_notice', '', 'RB World notice', 'A short message players see when they start RB World and on the city ticker (up to 200 characters). Empty: no notice.', 51);
CREATE TABLE IF NOT EXISTS world_bans (id TEXT PRIMARY KEY, name TEXT, reason TEXT, by TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS world_accounts (clerk_user_id TEXT PRIMARY KEY, player_id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS world_guests (player_id TEXT PRIMARY KEY, key_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS world_saves (player_id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS world_tickets (ticket TEXT PRIMARY KEY, player_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS world_nodes (id TEXT PRIMARY KEY, owner_id TEXT, owner_name TEXT, price INTEGER NOT NULL, takes INTEGER NOT NULL DEFAULT 0, claimed_at INTEGER, shield_until INTEGER, collected_at INTEGER);
CREATE INDEX IF NOT EXISTS world_nodes_owner ON world_nodes (owner_id);
CREATE TABLE IF NOT EXISTS world_fix (player_id TEXT PRIMARY KEY, lat REAL NOT NULL, lng REAL NOT NULL, at INTEGER NOT NULL, src TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS world_walk (player_id TEXT NOT NULL, day TEXT NOT NULL, metres REAL NOT NULL DEFAULT 0, PRIMARY KEY (player_id, day));
CREATE TABLE IF NOT EXISTS world_deals (id TEXT PRIMARY KEY, kind TEXT NOT NULL, lot INTEGER NOT NULL, from_id TEXT NOT NULL, from_name TEXT, to_id TEXT NOT NULL, to_name TEXT, amount INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, done_at INTEGER);
CREATE INDEX IF NOT EXISTS world_deals_to ON world_deals (to_id, status);
CREATE INDEX IF NOT EXISTS world_deals_from ON world_deals (from_id, status);
CREATE TABLE IF NOT EXISTS world_settle (id INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT NOT NULL, cash INTEGER NOT NULL DEFAULT 0, tokens INTEGER NOT NULL DEFAULT 0, note TEXT, created_at INTEGER NOT NULL, applied_at INTEGER);
CREATE INDEX IF NOT EXISTS world_settle_player ON world_settle (player_id, applied_at);
CREATE TABLE IF NOT EXISTS world_ad_stats (ad_id INTEGER NOT NULL, day TEXT NOT NULL, impressions INTEGER NOT NULL DEFAULT 0, viewable INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (ad_id, day));
